using System;using System.IO;using System.Net;using System.Net.Http;using System.Diagnostics;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Threading;using System.Threading.Tasks;using System.Security.Cryptography;using System.Web.Script.Serialization;using System.Runtime.InteropServices;
static class Updates {
 const string Feed="https://github.com/Ozan-roni/Pelge/releases/latest/download/desktop-update.json";
