 static async Task<Release> Latest(){using(var c=Client()){string json=await c.GetStringAsync(Feed);if(json.Length>16000)throw new InvalidDataException("Réponse trop volumineuse.");var r=Json.Deserialize<Release>(json);Validate(r);return r;}}
 static string Hash(string file){using(var s=File.OpenRead(file))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 static async Task<string> Download(Release r,Action<int> progress,CancellationToken cancel){Validate(r);string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Seraphim","Updates",new Version(r.version).ToString());Directory.CreateDirectory(folder);string file=Path.Combine(folder,"Seraphim-Setup.exe"),part=file+".part";if(File.Exists(file)&&new FileInfo(file).Length==r.size&&Hash(file).Equals(r.sha256,StringComparison.OrdinalIgnoreCase))return file;
  try{using(var c=Client())using(var response=await c.GetAsync(r.url,HttpCompletionOption.ResponseHeadersRead,cancel)){response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength.HasValue&&response.Content.Headers.ContentLength.Value!=r.size)throw new IOException("Taille de téléchargement inattendue.");using(var source=await response.Content.ReadAsStreamAsync())using(var output=File.Create(part)){var buffer=new byte[65536];long count=0;int n;while((n=await source.ReadAsync(buffer,0,buffer.Length,cancel))>0){count+=n;if(count>r.size)throw new IOException("Téléchargement trop volumineux.");await output.WriteAsync(buffer,0,n,cancel);progress((int)(count*100/r.size));}if(count!=r.size)throw new IOException("Téléchargement incomplet.");}}cancel.ThrowIfCancellationRequested();if(!Hash(part).Equals(r.sha256,StringComparison.OrdinalIgnoreCase))throw new IOException("L’intégrité du téléchargement n’a pas été confirmée.");if(File.Exists(file))File.Delete(file);File.Move(part,file);return file;}catch{if(File.Exists(part))File.Delete(part);throw;}
 }
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr hwnd,int msg,IntPtr w,IntPtr l);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindWindow(string cls,string title);
 [DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr hwnd,out uint pid);
 static void Apply(string file){string managed=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Seraphim");if(!String.Equals(Root,managed,StringComparison.OrdinalIgnoreCase)||!File.Exists(Path.Combine(Root,"installation-seraphim.txt")))throw new IOException("Pour cette copie portable, lancez l’installateur téléchargé depuis le dossier de téléchargements Seraphim.");var process=Process.GetProcessesByName("Seraphim").FirstOrDefault(p=>{try{return String.Equals(p.MainModule.FileName,Path.Combine(Root,"Seraphim.exe"),StringComparison.OrdinalIgnoreCase);}catch{return false;}});int id=process==null?0:process.Id;IntPtr hwnd=process==null?IntPtr.Zero:process.MainWindowHandle;if(hwnd==IntPtr.Zero&&process!=null){uint pid;var candidate=FindWindow(null,"Seraphim");GetWindowThreadProcessId(candidate,out pid);if(pid==(uint)id)hwnd=candidate;}if(process!=null&&hwnd==IntPtr.Zero)throw new IOException("Ouvrez Seraphim ou quittez-le depuis son icône, puis réessayez.");Process.Start(new ProcessStartInfo(file,"--update "+id){UseShellExecute=true});if(hwnd!=IntPtr.Zero)PostMessage(hwnd,0x8063,IntPtr.Zero,IntPtr.Zero);}
 static void Show(Release known=null){var f=new Form {Text="Mises à jour · Seraphim",Width=540,Height=280,StartPosition=FormStartPosition.CenterScreen,BackColor=Color.FromArgb(20,21,29),ForeColor=Color.White,Font=new Font("Segoe UI",10),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false};var text=new Label {Text="Recherche de la dernière version…",Left=25,Top=25,Width=480,Height=90};var bar=new ProgressBar {Left=25,Top=125,Width=475,Height=12};var action=new Button {Text="Rechercher",Enabled=false,Left=25,Top=161,Width=475,Height=42,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(189,169,228)};f.Controls.AddRange(new Control[]{text,bar,action});Release latest=known;var cancel=new CancellationTokenSource();f.FormClosing+=delegate{cancel.Cancel();};f.Shown+=async delegate{try{if(latest==null)latest=await Latest();if(new Version(latest.version)<=Current){text.Text="Seraphim est à jour.\nVersion installée : "+Current;action.Text="Fermer";action.Enabled=true;action.Click+=delegate{f.Close();};return;}text.Text="Version "+latest.version+" disponible.\nVos préférences, votre compte et votre planning sont conservés.";action.Text="Télécharger et installer";action.Enabled=true;action.Click+=async delegate{action.Enabled=false;try{string file=await Download(latest,p=>{bar.Value=p;text.Text="Téléchargement vérifié depuis GitHub · "+p+" %";},cancel.Token);if(cancel.IsCancellationRequested)return;if(MessageBox.Show(f,"Installer la version "+latest.version+" ? Seraphim sera fermé, la session sera désactivée et l’application redémarrera. Rechargez ensuite l’extension dans Chrome/Edge.","Mise à jour Seraphim",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){Apply(file);f.Close();}else{action.Enabled=true;action.Text="Installer la mise à jour";}}catch(OperationCanceledException){}catch(Exception ex){if(!f.IsDisposed){text.Text=ex.Message;action.Enabled=true;action.Text="Réessayer";}}};}catch(Exception ex){text.Text="La vérification est indisponible.\n"+ex.Message;action.Text="Fermer";action.Enabled=true;action.Click+=delegate{f.Close();};}};Application.Run(f);}
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();try{if(args.Length==2&&args[0]=="--test"){int rejected=0;foreach(string url in new[]{"http://github.com/Ozan-roni/Pelge/releases/download/v9.0.0/Seraphim-Setup.exe","https://evil.example/setup.exe","https://github.com/other/repo/releases/download/v9.0.0/Seraphim-Setup.exe"})try{Validate(new Release {version="9.0.0",url=url,size=2000,sha256=new string('a',64)});}catch{rejected++;}if(rejected!=3)throw new Exception("URL rejection failed");Validate(new Release{version="9.0.0",url="https://github.com/Ozan-roni/Pelge/releases/download/v9.0.0/Seraphim-Setup.exe",size=2000,sha256=new string('a',64)});File.WriteAllText(args[1],"PASS URLs HTTPS et dépôt exact, versions, tailles et empreintes requises.");return 0;}if(args.Length==2&&args[0]=="--verify-release"){var r=Latest().GetAwaiter().GetResult();string file=Download(r,p=>{},CancellationToken.None).GetAwaiter().GetResult();File.WriteAllText(args[1],"PASS release "+r.version+", téléchargement "+new FileInfo(file).Length+" octets et SHA-256 confirmé. Aucun exécutable lancé.");return 0;}if(args.Length==1&&args[0]=="--quiet"){string stamp=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Seraphim","last-update-check.txt");DateTime last;if(File.Exists(stamp)&&DateTime.TryParse(File.ReadAllText(stamp),out last)&&DateTime.UtcNow-last<TimeSpan.FromHours(24))return 0;Directory.CreateDirectory(Path.GetDirectoryName(stamp));File.WriteAllText(stamp,DateTime.UtcNow.ToString("o"));var r=Latest().GetAwaiter().GetResult();if(new Version(r.version)<=Current)return 0;var icon=new NotifyIcon {Text="Mise à jour Seraphim",Visible=true,Icon=new Icon(Path.Combine(Root,"Seraphim-Premium.ico"))};var context=new ApplicationContext();var timer=new System.Windows.Forms.Timer {Interval=90000};timer.Tick+=delegate{context.ExitThread();};bool selected=false;icon.BalloonTipClicked+=delegate{selected=true;context.ExitThread();};icon.BalloonTipTitle="Seraphim "+r.version+" disponible";icon.BalloonTipText="Cliquez pour préparer la mise à jour. Vos données seront conservées.";icon.ShowBalloonTip(10000);timer.Start();Application.Run(context);timer.Stop();icon.Dispose();if(selected)Show(r);return 0;}Show();return 0;}catch(Exception ex){if(args.Length==2)File.WriteAllText(args[1]+".error.txt",ex.Message);else if(args.Length==0)MessageBox.Show(ex.Message,"Seraphim");return 1;}}
}
